.darma-loader-tw-progress-indeterminate { position: relative; overflow: hidden; width: var(--loader-size, 180px); height: calc(var(--loader-size, 180px) * .06); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #0ea5e9) 18%, transparent); }
.darma-loader-tw-progress-indeterminate span { position: absolute; top: 0; bottom: 0; left: 0; width: 40%; border-radius: 9999px; background: var(--loader-color, #0ea5e9); animation: darma-loader-tw-progress-indeterminate-twSlide calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
@keyframes darma-loader-tw-progress-indeterminate-twSlide { 0% { transform: translateX(-110%); } 100% { transform: translateX(280%); } }

